'{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "description": "P28 C / V3 the morning after: top-12 fears by people as a child vs now; lines draw on open; hover spotlights one fear.",
 "width": 1237,
 "height": 440,
 "padding": 0,
 "autosize": "none",
 "signals": [
  {
   "name": "t0",
   "init": "now()"
  },
  {
   "name": "clock",
   "init": "0",
   "on": [
    {
     "events": {
      "type": "timer",
      "throttle": 40
     },
     "update": "min(now() - t0, 4600)"
    }
   ]
  },
  {
   "name": "t",
   "update": "min(1, clock / 4500)"
  },
  {
   "name": "hovD",
   "value": null,
   "on": [
    {
     "events": "@lbl0:mouseover, @lbl1:mouseover, @line:mouseover",
     "update": "datum"
    },
    {
     "events": "@lbl0:mouseout, @lbl1:mouseout, @line:mouseout",
     "update": "null"
    }
   ]
  },
  {
   "name": "hovF",
   "update": "hovD ? hovD.label : null"
  }
 ],
 "data": [
  {
   "name": "dataset"
  },
  {
