  {
   "name": "rows",
   "source": "dataset",
   "transform": [
    {
     "type": "filter",
     "expr": "datum.Category !== ''Other Responses''"
    },
    {
     "type": "formula",
     "as": "c",
     "expr": "datum[''People Childhood''] || 0"
    },
    {
     "type": "formula",
     "as": "a",
     "expr": "datum[''People Adult''] || 0"
    },
    {
     "type": "lookup",
     "from": "labels",
     "key": "Fear",
     "fields": [
      "Fear"
     ],
     "values": [
      "label"
     ],
     "as": [
      "lab0"
     ]
    },
    {
     "type": "formula",
     "as": "label",
     "expr": "datum.lab0 || datum.FearShort || datum.Fear"
    },
    {
     "type": "window",
     "sort": {
      "field": [
       "c",
       "label"
      ],
      "order": [
       "descending",
       "ascending"
      ]
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "lr"
     ]
    },
    {
     "type": "window",
     "sort": {
      "field": [
       "a",
       "label"
      ],
      "order": [
       "descending",
       "ascending"
      ]
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "rr"
     ]
    },
    {
     "type": "filter",
     "expr": "datum.lr <= 12 || datum.rr <= 12"
    },
    {
     "type": "formula",
     "as": "y1",
     "expr": "82 + (min(datum.lr, 13) - 0.5) * 28"
    },
    {
     "type": "formula",
     "as": "y2",
     "expr": "82 + (min(datum.rr, 13) - 0.5) * 28"
    },
    {
     "type": "formula",
     "as": "both",
     "expr": "datum.lr <= 12 && datum.rr <= 12"
    },
    {
     "type": "formula",
     "as": "col",
     "expr": "datum.rr < datum.lr ? ''#5B2DBF'' : datum.rr > datum.lr ? ''#C8006E'' : ''#5A5470''"
    }
   ]
  },
  {
   "name": "stay",
   "source": "rows",
   "transform": [
    {
     "type": "filter",
     "expr": "datum.both"
    }
