      "signal": "datum.both ? ''M330 '' + datum.y1 + '' C618.5 '' + datum.y1 + '' 618.5 '' + datum.y2 + '' 907 '' + datum.y2 : datum.lr <= 12 ? ''M330 '' + datum.y1 + '' h'' + (115.4 * (1 - pow(1 - clamp(t * 1.5 - 0.3, 0, 1), 3))) : ''M907 '' + datum.y2 + '' h'' + (-115.4 * (1 - pow(1 - clamp(t * 1.5 - 0.3, 0, 1), 3)))"
     },
     "stroke": {
      "signal": "datum.both ? datum.col : (datum.lr <= 12 ? ''#C8006E'' : ''#5B2DBF'')"
     },
     "strokeDash": {
      "signal": "datum.both ? [1237, 1237] : [5, 5]"
     },
     "strokeDashOffset": {
      "signal": "datum.both ? 1237 * (1 - (1 - pow(1 - clamp(t * 1.5 - 0.3, 0, 1), 3))) : 0"
     },
     "fill": {
      "value": "transparent"
     },
     "opacity": {
      "signal": "hovF ? (hovF === datum.label ? 1 : 0.14) : (datum.both ? 0.95 : 0.6)"
     },
     "strokeWidth": {
